Here's a Python function that will determine if a given number is prime:

```python
def is_prime(n):
    # Special case for 1
    if n == 1:
        return False

    # Check for odd vs even numbers
    if n % 2 == 0:
        # 2 is a prime number, so a number with 2 as its factor is excluded from potential optimisation.
        return n == 2 and True

    # No factor checked so far, perform trial division
    # (slower)
    sq = int(n ** 0.5)
    for I in range(1, sq + 1):
        if (n % I) == 0:
            return False

    # Faster implementation using the Compositeness Test (based on the fact that the square of a non-trivial factor of n is less than n itself)
    primes = [2]  # 2 and 3 are prime, exclude them from potential optimization.
    while not n % 2 == 0:
        upper_bound = int(n ** 0.5)
        for I in range(3, upper_bound + 1, 2):
            if n % I == 0:
                break
        primes.append(n)  # n is composite, exclude possibility of optimization

    return n not in primes
``

