class DoublePileQueue:

    def __init__(self):
        """ Initializes the queue using two piles, one for the front and one for the rear """
        self.front_pile = []
        self.rear_pile = None

        # Initialize the two piles as empty piles, even though they will be manipulated later
        self.is_empty = True

    # Methods related to queue operations

    def enqueue(self, item):
        """ Add an item to the rear of the queue """
        if self.rear_pile is None:
            self.rear_pile = [item]
        else:
            self.rear_pile.append(item)

    def dequeue(self, item):
        """ Remove an item from the front of the queue """
        if not self.is_empty:
            try:
                self.front_pile.remove(item)
            except KeyError:
                raise ValueError("Item is not in the front of the queue")

    def front(self):
        """ Returns the element at the front of the queue (without removing it) """
        if not self.is_empty:
            return self.front_pile[-1]

    def rear(self):
        """ Returns the element at the back of the queue (without removing it) """
        if not self.is_empty and self.rear_pile is not None:
            return self.rear_pile[-1]

    @property
    def is_empty(self):
        """ Indicates if the queue is empty """
        return False if self.rear_pile or self.front_pile else True

    def build(self, item_list):
        """ Builds the queue given a list of items to place in the queue, by iterating through the list to add the items to the back of the queue. """
        for element in item_list:
